export function at(value,path){if(!Array.isArray(path)||path.some(k=>typeof k!=='string'&&typeof k!=='number'||['__proto__','prototype','constructor'].includes(String(k))))throw Error('Invalid grammar path');return path.reduce((v,k)=>v?.[k],value);}
export function declarationFor(presentation,tool,path){return(presentation?.collections||[]).find(d=>d.source?.tool===tool&&JSON.stringify(d.source.path)===JSON.stringify(path));}
export function distinctValues(items,path){return[...new Map(items.map(v=>at(v,path)).filter(v=>v!==undefined&&v!==null).map(v=>[JSON.stringify(v),v])).values()].sort((a,b)=>String(a).localeCompare(String(b)));}
export function filterItems(items,definition,values){return items.filter(item=>(definition.filters||[]).every(f=>{const selected=values[f.id];if(f.kind==='toggle'?!selected:selected===''||selected===undefined)return true;const actual=at(item,f.path),expected=f.kind==='toggle'?f.value:selected;switch(f.operator){case'contains-folded':return String(actual??'').toLocaleLowerCase().includes(String(expected).toLocaleLowerCase());case'equal':return actual===expected;case'not-equal':return actual!==expected;default:throw Error('Unsupported declared filter operator: '+f.operator);}}));}
export function pageItems(items,definition,values,page=1,size){const filtered=filterItems(items,definition,values),p=definition.pagination;if(!p)return{items:filtered,page:1,pages:1,start:filtered.length?1:0,end:filtered.length,filtered:filtered.length,total:items.length};const chosen=size??p.defaultSize;if(!p.sizes.includes(chosen)||!Number.isSafeInteger(chosen)||chosen<1)throw Error('Page size is not declared by the MCP grammar');const pages=Math.max(1,Math.ceil(filtered.length/chosen)),current=Math.max(1,Math.min(page,pages)),offset=(current-1)*chosen;return{items:filtered.slice(offset,offset+chosen),page:current,pages,start:filtered.length?offset+1:0,end:Math.min(offset+chosen,filtered.length),filtered:filtered.length,total:items.length};}
export function bindArguments(bindings,item){if(bindings&&typeof bindings==='object'&&!Array.isArray(bindings)){if(Object.hasOwn(bindings,'itemPath')){const value=at(item,bindings.itemPath);if(value===undefined)throw Error('Declared action source is missing');return value;}if(Object.hasOwn(bindings,'literal'))return bindings.literal;return Object.fromEntries(Object.entries(bindings).map(([k,v])=>[k,bindArguments(v,item)]));}throw Error('Action arguments need declared item paths or literal values');}
export function template(text,values){return String(text).replace(/\{([a-z]+)\}/g,(_,k)=>String(values[k]??''));}
